import type { Browser, PDFOptions } from "puppeteer-core";
import puppeteer from "puppeteer-core";

export type HtmlToPdfOptions = {
  landscape?: boolean;
  /** When false, omit the bottom “Generated by…” PDF footer. Default true. */
  attributionFooter?: boolean;
};

const HEADER_TEMPLATE = `<div style="width:100%;height:100%;margin:0;padding:0;background:#ffffff;font-size:0;"></div>`;
const FOOTER_TEMPLATE = `<div style="width:100%;height:100%;margin:0;padding:4px 8mm 0;box-sizing:border-box;font-family:Arial,sans-serif;color:#000;background:#ffffff;-webkit-print-color-adjust:exact;print-color-adjust:exact;"><div style="border-top:1px solid #000;margin:0 0 2px;width:100%;height:0;"></div><div style="font-size:8px;font-style:italic;text-align:right;">Generated by Sales Management Application</div></div>`;

/** Cap request HTML to avoid unbounded Chromium memory use. */
export const MAX_PRINT_HTML_BYTES = 5 * 1024 * 1024;

function isServerlessRuntime(): boolean {
  return Boolean(
    process.env.VERCEL ||
      process.env.AWS_LAMBDA_FUNCTION_NAME ||
      process.env.FUNCTION_NAME,
  );
}

let browserPromise: Promise<Browser> | null = null;

async function launchBrowser(): Promise<Browser> {
  if (isServerlessRuntime()) {
    // Lightweight Chromium build that fits Vercel serverless limits.
    const chromium = await import("@sparticuz/chromium");
    return puppeteer.launch({
      args: chromium.default.args,
      defaultViewport: { width: 794, height: 1123, deviceScaleFactor: 1 },
      executablePath: await chromium.default.executablePath(),
      headless: true,
    });
  }

  // Local / PM2: prefer full puppeteer (bundled Chrome), else env path.
  try {
    const full = await import("puppeteer");
    return full.default.launch({
      headless: true,
      args: [
        "--no-sandbox",
        "--disable-setuid-sandbox",
        "--disable-dev-shm-usage",
        "--font-render-hinting=none",
      ],
    });
  } catch {
    const executablePath = process.env.PUPPETEER_EXECUTABLE_PATH;
    if (!executablePath) {
      throw new Error(
        "No Chromium available. Install puppeteer, or set PUPPETEER_EXECUTABLE_PATH.",
      );
    }
    return puppeteer.launch({
      executablePath,
      headless: true,
      args: [
        "--no-sandbox",
        "--disable-setuid-sandbox",
        "--disable-dev-shm-usage",
        "--font-render-hinting=none",
      ],
    });
  }
}

async function getBrowser(): Promise<Browser> {
  if (!browserPromise) {
    browserPromise = launchBrowser().catch((err) => {
      browserPromise = null;
      throw err;
    });
  }
  return browserPromise;
}

export async function closePdfBrowser(): Promise<void> {
  const pending = browserPromise;
  browserPromise = null;
  if (!pending) return;
  try {
    const browser = await pending;
    await browser.close();
  } catch {
    // Already closed or failed to launch.
  }
}

export async function renderHtmlToPdf(
  html: string,
  options: HtmlToPdfOptions = {},
): Promise<Uint8Array> {
  if (typeof html !== "string" || html.trim().length === 0) {
    throw new Error("Print HTML is required");
  }
  if (Buffer.byteLength(html, "utf8") > MAX_PRINT_HTML_BYTES) {
    throw new Error("Print HTML exceeds the maximum allowed size");
  }

  const landscape = options.landscape === true;
  const showAttribution = options.attributionFooter !== false;
  const browser = await getBrowser();
  const page = await browser.newPage();

  try {
    await page.setContent(html, {
      waitUntil: "load",
      timeout: 30_000,
    });
    // String form avoids needing DOM libs in the Node tsconfig.
    await page.evaluate(`(async () => {
      if (document.fonts && document.fonts.ready) await document.fonts.ready;
      await new Promise((resolve) => {
        requestAnimationFrame(() => requestAnimationFrame(resolve));
      });
      return true;
    })()`);

    const pdfOptions: PDFOptions = {
      printBackground: true,
      preferCSSPageSize: true,
      landscape,
      format: "A4",
      displayHeaderFooter: showAttribution,
    };

    if (showAttribution) {
      pdfOptions.headerTemplate = HEADER_TEMPLATE;
      pdfOptions.footerTemplate = FOOTER_TEMPLATE;
      // Inches — match Electron custom margins (top clears header band).
      pdfOptions.margin = {
        top: "0.42in",
        bottom: "0.55in",
        left: "0.25in",
        right: "0.25in",
      };
    } else {
      pdfOptions.margin = {
        top: "0",
        bottom: "0",
        left: "0",
        right: "0",
      };
    }

    const buffer = await page.pdf(pdfOptions);
    if (!buffer || buffer.byteLength === 0) {
      throw new Error("PDF generation returned empty output");
    }
    return new Uint8Array(buffer);
  } finally {
    await page.close().catch(() => undefined);
  }
}
